-- 39 Lantern Orchard: carries the lantern after the mouse, lets it flicker,
-- and hangs it where you click. Every shadow is traced from its sprite's
-- pixels by the engine (`light_occluder.from_alpha`).
-- Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/39-lantern-orchard.scene"
local post_on = nav.post_all_on(SCENE)
local captions = true
local lantern, glow, status
local x, y = -120, 40
local hung = false
local t = 0

local function refresh()
    if status then UI.set_text(status, hung and "the lantern hangs - click to take it" or "carrying the lantern") end
end

function init(entity)
    lantern = Entity.find_by_name("Lantern")
    glow = Entity.find_by_name("LanternGlow")
    status = Entity.find_by_name("Status")
    refresh()
end

function update(entity, dt)
    nav.tick(SCENE)
    nav.post_keys(post_on)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if lantern == nil then return end
    t = t + dt
    if Input.is_mouse_left_just_pressed() then
        hung = not hung
        refresh()
    end
    if not hung then
        -- Carried: it trails the hand a little.
        local mx, my = Input.get_mouse_world_position()
        local k = math.min(1, dt * 10)
        x = x + (mx - x) * k
        y = y + (my - y) * k
    end
    -- A sway when hung, and a flame's flicker either way.
    local sx = hung and math.sin(t * 1.7) * 3 or 0
    Transform.set_position(lantern, x + sx, y)
    if glow then Transform.set_position(glow, x + sx, y) end
    local flicker = 2.2 + math.sin(t * 13) * 0.08 + math.sin(t * 7.3 + 1) * 0.1
    Lighting.set_intensity(lantern, flicker)
end
